sel=[(283,'Dialogo: personaje lateral y caja independiente','Composicion mas directa para Amber. Placa de nombre sobre el texto; retrato fuera del area de lectura.'),(950,'Dialogo: retrato y pergamino','Referencia para lectura narrativa; evitar trasladar texto incrustado y una caja demasiado pequena.'),(772,'Kit de paneles de pergamino','Referencia de paneles, separadores, listas y botones; reconstruir piezas a resolucion de uso.'),(782,'Kit RPG de pergaminos e inventario','Util para contratos, misiones, diario y recompensas. Imagen pequena: no tratar como atlas final.'),(786,'Placas magicas ornamentales','Nombres, rarezas o elecciones especiales; ornamentacion mas luminosa que el dialogo base.'),(788,'Paneles neon','Reservar para interfaz tecnologica o modos especiales, sin mezclar por defecto con pergamino.'),(1209,'Marco horizontal sobrio','Buen candidato visual para caja de dialogo; preservar esquinas y ampliar zona central.'),(1249,'Separadores dorados','Utiles para titulos o nombre del interlocutor; usar ornamentacion fuera del texto.'),(1265,'Retrato circular y placa gotica','Adecuado para cabecera compacta o NPC de faccion; demasiado detalle para botones pequenos.'),(1288,'Marco angular dorado','Referencia de bordes discretos y jerarquia; composicion completa con fondo y texto ya integrados.'),(271,'Lista de conversaciones con retratos','Referencia para historial de conversaciones y entradas por personaje.'),(709,'Carta de pergamino','Referencia para mensajes, contratos y misiones escritas.')]
